// 新命令只承載本人接受/撤回；原死亡activation與原Legacy三表不分叉。
#include "biological_control_commands.hpp"
#include "succession_personal_assets.hpp"
namespace hanmo::resident {
Outcome<BiologicalControlCommand> decode_biological_control_command(const StableId& kind,const BoundaryValue& args){try{auto unique=validate_succession_json_unique(args);if(!unique.ok)return {false,{},unique.error};using namespace boundary;BiologicalControlCommand c;c.kind=kind;
 if(kind=="family_biological_accept"){fields(args,{"request_id","successor_actor_id"},{},kind);c.successor_actor_id=get_string(args,"successor_actor_id",kind);}
 else if(kind=="family_biological_revoke"){fields(args,{"request_id","consent_fact_id"},{},kind);c.consent_fact_id=get_string(args,"consent_fact_id",kind);}else fail("UnknownBiologicalControlCommand",kind);
 c.request_id=get_string(args,"request_id",kind);for(const auto* id:{&c.request_id,kind=="family_biological_accept"?&c.successor_actor_id:&c.consent_fact_id})if(id->empty()||id->size()>256)fail("InvalidBiologicalControlCommand",kind);return {true,std::move(c),{}};
}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Outcome<LegacyControlDecisionQuote> preview_biological_control_command(const BiologicalControlDecisionContext& x,const FamilyState& family,const FamilyDeathState& deaths,const FamilyDeathOriginRead& death_read,const InteractionState& interactions,const InteractionAccess& access,const FamilyLegacyState& legacy,const FamilyLegacyPlayableRead& playable,const StableId& actor,const BiologicalControlCommand& command,const DiscipleControlRelationContext* disciple,const CollateralControlDecisionContext* collateral){
 const auto& c=x.people.common;if(actor!=c.state().metadata.player_actor_id)return {false,{},common_failure("PlayerCommandAuthorityRequired").error};if(!x.catalog.definitions.find(command.request_id))return {false,{},common_failure("BiologicalControlRequestMismatch").error};auto valid=validate_family_legacy(c,family,deaths,death_read,x.people.catalog,x.interaction_catalog,x.original_requests,legacy,playable,disciple,&x,collateral);if(!valid.ok)return {false,{},valid.error};StableId child=command.successor_actor_id;
 if(command.kind=="family_biological_accept"){if(child.empty()||!command.consent_fact_id.empty())return {false,{},common_failure("InvalidBiologicalControlCommand").error};}
 else if(command.kind=="family_biological_revoke"){if(!child.empty()||command.consent_fact_id.empty())return {false,{},common_failure("InvalidBiologicalControlCommand").error};const auto* accepted=legacy.consents.find(command.consent_fact_id);if(!accepted||!accepted->source.biological_origin||accepted->source.request_id!=command.request_id||accepted->source.predecessor_actor_id!=actor)return {false,{},common_failure("BiologicalControlRevocationSourceMismatch").error};for(const auto& r:legacy.revocations.rows())if(r.second.consent_fact_id==command.consent_fact_id)return {false,{},common_failure("LegacyConsentAlreadyClosed").error};for(const auto& a:legacy.activations.rows())if(a.second.consent_fact_id==command.consent_fact_id)return {false,{},common_failure("LegacyConsentAlreadyClosed").error};child=accepted->source.successor_actor_id;}
 else return {false,{},common_failure("UnknownBiologicalControlCommand").error};
 return preview_biological_control_decision(x,interactions,access,actor,child,command.request_id,command.kind=="family_biological_accept"?"accept":"revoke");
}
Outcome<FamilyEffect> apply_biological_control_command(CommonStore& c,const BiologicalControlDecisionContext& x,const FamilyState& family,const FamilyDeathState& deaths,const FamilyDeathOriginRead& death_read,const InteractionState& interactions,const InteractionAccess& access,FamilyLegacyState& legacy,const FamilyLegacyPlayableRead& playable,const StableId& actor,const BiologicalControlCommand& command,const LegacyControlDecisionQuote& quote,const DiscipleControlRelationContext* disciple,const CollateralControlDecisionContext* collateral){
 if(&c!=&x.people.common)return {false,{},common_failure("BiologicalControlCandidateMismatch").error};auto fresh=preview_biological_control_command(x,family,deaths,death_read,interactions,access,legacy,playable,actor,command,disciple,collateral);if(!fresh.ok)return {false,{},fresh.error};if(!legacy_control_decision_equal(fresh.value.decision,quote.decision))return {false,{},common_failure("StaleBiologicalControlDecision").error};auto fact=record_family_legacy_decision(c,family,deaths,death_read,interactions,x.interaction_catalog,access,x.original_requests,legacy,quote,command.consent_fact_id,playable,disciple,&x,collateral);if(!fact.ok)return {false,{},fact.error};FamilyEffect effect;effect.success=true;effect.fact_id=fact.value;effect.heir_actor_id=quote.decision.successor_actor_id;effect.player_actor_id=c.state().metadata.player_actor_id;return {true,std::move(effect),{}};
}
}
